def mock_hit(call, gold):
    # virtual execution: the request is matched, never sent
    return (call.host == gold.host
            and call.endpoint == gold.endpoint
            and call.method == gold.method)

def robust_hit(code, call, gold):
    # Robust adds defensive handling on top of a Mock hit
    return (mock_hit(call, gold)
            and checks_status_code(code)
            and handles_exceptions(code))
